function maskS2(img) {
  var scl  = img.select('SCL');
  var mask = scl.neq(3).and(scl.neq(8)).and(scl.neq(9))
                        .and(scl.neq(10)).and(scl.neq(11));
  return img.updateMask(mask).divide(10000);
}

